const header=document.querySelector('.site-header');const menu=document.querySelector('.menu');if(menu){menu.addEventListener('click',()=>{const open=header.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});}document.querySelectorAll('.lead-form').forEach(form=>{const button=form.querySelector('.whatsapp-submit');if(!button)return;button.addEventListener('click',()=>{if(!form.reportValidity())return;if(form.elements.website?.value)return;const data=new FormData(form);const lines=['Goedendag, ik wil via de website een aanvraag indienen.'];const labels={formulier:'Type aanvraag',voornaam:'Voornaam',achternaam:'Achternaam',naam:'Naam',bedrijf:'Bedrijf',email:'E-mail',telefoon:'Telefoon',postcode:'Postcode',huisnummer:'Huisnummer',toevoeging:'Toevoeging',plaats:'Plaats',klanttype:'Type klant','werkzaamheden[]':'Werkzaamheden',omschrijving:'Omschrijving',planning:'Planning',contactvoorkeur:'Contactvoorkeur',storing:'Type storing',gewenste_tijd:'Gewenst moment'};for(const [key,value] of data.entries()){if(key==='website'||value instanceof File||!String(value).trim())continue;lines.push((labels[key]||key)+': '+value);}lines.push('Foto’s of documenten stuur ik eventueel in dit WhatsApp-gesprek.');form.querySelector('.form-status').textContent='WhatsApp wordt geopend. Controleer het bericht en druk daar op verzenden.';window.open('https://wa.me/31613271261?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener');});});